from rp_clinical_trial
where clinical_trial_id = #{clinical_trial_id} and lang = #{lang}

	select record_id,clinical_trial_id,title,condition,phase,location,inclusion_criteria,exclusion_criteria,modified,update_by,unix_timestamp(str_to_date(update_date, '%Y-%m-%d %H:%i:%s')) as update_date
	from rp_clinical_trial
	where clinical_trial_id in 

      #{item}

    and lang = #{lang}

select clinical_trial_id,official_title as title,recruiting_condition,phase,location,inclusion_criteria,exclusion_criteria,unix_timestamp(str_to_date(update_date, '%Y-%m-%d %H:%i:%s')) as update_date
from nkb_clinical_trial_evw
where clinical_trial_id = #{clinical_trial_id} and lang = #{lang}

select count(*) from rp_clinical_trial

	modified=1

		and update_date >= #{before_date}


		and update_date < #{after_date}

select record_id,clinical_trial_id,lang,title,recruiting_condition,phase,location,modified,update_by,date_format(update_date,'%Y-%m-%d %H:%i:%s') as update_date 
from rp_clinical_trial

	modified=1

		and update_date >= #{before_date}


		and update_date < #{after_date}


limit #{pageNo},#{pageSize}

select record_id,clinical_trial_id,lang,title,recruiting_condition,phase,location,modified,update_by,date_format(update_date,'%Y-%m-%d %H:%i:%s') as update_date 
from rp_clinical_trial

	modified=1

		and update_date >= #{before_date}


		and update_date < #{after_date}

